  color: #253947;
  background: #f1f8f6;
  border: 2px solid #bbd9ce;
  border-radius: 18px;
}
h1 { color: #265b50; }
.brett {
  display: grid;
  grid-template-columns: repeat(3, 70px);
  justify-content: center;
  gap: 7px;
  margin: 18px auto;
}
.feld {
  width: 70px;
  height: 70px;
  border: 2px solid #a9c9bd;
  border-radius: 8px;
