  cursor: pointer;
}
.feld:hover { background: #e4f4ed; }
button.neustart {
  padding: 10px 15px;
  color: white;
  background: #367866;
  border: 0;
  border-radius: 8px;
  cursor: pointer;
}
#meldung { min-height: 1.5em; font-weight: bold; }

